import math, re
from typing import List, Dict, Any

# ----------------------------------------------------------------------
# Parameters tuned from exploratory analysis
# ----------------------------------------------------------------------
FRAME_TIME = 5.0 / 127.0      # seconds per frame
COLLISION_DIST = 0.6          # approximate contact distance

# ----------------------------------------------------------------------
# Helper: parse motion log for a scope
# ----------------------------------------------------------------------
def _parse_motion(doc: Dict[str, Any], scope: str) -> Dict[str, List[Dict[str, float]]]:
    """
    Return `{obj_id: list of records}` for the requested scope.
    Each record contains: frame, x, y, vx, vy, speed.
    """
    scope_node = next((n for n in doc["nodes"] if n.get("title") == scope), None)
    if not scope_node:
        return {}

    motion = {}
    for child_id in scope_node.get("children", []):
        child = next((n for n in doc["nodes"] if n["node_id"] == child_id), None)
        if child and child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            for row in child["table"]["rows"]:
                try:
                    frame = int(row[0])
                    oid = row[1].split()[0]
                    x, y, vx, vy, speed = map(float, row[2:7])
                except Exception:
                    continue
                motion.setdefault(oid, []).append(
                    {"frame": frame, "x": x, "y": y, "vx": vx, "vy": vy, "speed": speed}
                )
    for lst in motion.values():
        lst.sort(key=lambda r: r["frame"])
    return motion

# ----------------------------------------------------------------------
# Simulation routine
# ----------------------------------------------------------------------
def simulate(doc: Dict[str, Any],
             scope: str,
             removed=(),
             horizon=None,
             start=0.0) -> List[Dict[str, Any]]:
    """
    Simulate motion for the objects in *scope*.
    Returns collision events (time as frame number) occurring after *start*.
    """
    # 1. Set of objects to consider
    obj_ids = {e["id"] for e in entities(doc, scope)} - set(removed)

    # 2. Load motion logs
    motion = _parse_motion(doc, scope)

    # 3. Initialise states at the start time
    states = {}
    for oid in obj_ids:
        recs = motion.get(oid, [])
        if not recs:
            continue
        first_f, last_f = recs[0]["frame"], recs[-1]["frame"]

        # Find last record <= start
        state = None
        for r in recs:
            if r["frame"] <= start:
                state = r

        if state:
            dt = (start - state["frame"]) * FRAME_TIME
            x = state["x"] + state["vx"] * dt
            y = state["y"] + state["vy"] * dt
            states[oid] = {
                "frame": start,
                "x": x,
                "y": y,
                "vx": state["vx"],
                "vy": state["vy"],
                "speed": state["speed"],
                "first_frame": first_f,
                "last_frame": last_f,
            }
        else:
            r0 = recs[0]
            states[oid] = {
                "frame": r0["frame"],
                "x": r0["x"],
                "y": r0["y"],
                "vx": r0["vx"],
                "vy": r0["vy"],
                "speed": r0["speed"],
                "first_frame": r0["frame"],
                "last_frame": last_f,
            }

    # 4. Simulation limits
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # 5. Collision state tracking
    pair_active: Dict[tuple, bool] = {}

    # 6. Simulation loop – step one frame at a time
    cur_frame = int(math.floor(start))
    events: List[Dict[str, Any]] = []

    while cur_frame < int(math.floor(horizon)):
        t_seconds = cur_frame * FRAME_TIME

        # Move every visible object
        for st in states.values():
            if t_seconds < st["first_frame"] * FRAME_TIME:
                continue
            st["x"] += st["vx"] * FRAME_TIME
            st["y"] += st["vy"] * FRAME_TIME

        # Check collisions between all pairs
        oid_list = list(states.keys())
        for i in range(len(oid_list)):
            oi = oid_list[i]
            sti = states[oi]
            if t_seconds < sti["first_frame"] * FRAME_TIME:
                continue
            for j in range(i + 1, len(oid_list)):
                oj = oid_list[j]
                stj = states[oj]
                if t_seconds < stj["first_frame"] * FRAME_TIME:
                    continue

                pair = tuple(sorted((oi, oj)))
                dx = sti["x"] - stj["x"]
                dy = sti["y"] - stj["y"]
                d = math.hypot(dx, dy)

                active = pair_active.get(pair, False)
                if d <= COLLISION_DIST:
                    if not active:
                        event_time = cur_frame + 1.0  # event occurs after this frame step
                        if event_time >= start:
                            events.append({
                                "time": event_time,
                                "kind": "collision",
                                "participants": [oi, oj],
                            })
                        # Simple elastic response (equal mass)
                        # Normal vector
                        if d == 0:
                            nx, ny = 1.0, 0.0
                        else:
                            nx, ny = dx / d, dy / d
                        rvx, rvy = sti["vx"] - stj["vx"], sti["vy"] - stj["vy"]
                        rel = rvx * nx + rvy * ny
                        sti["vx"] -= rel * nx
                        sti["vy"] -= rel * ny
                        stj["vx"] += rel * nx
                        stj["vy"] += rel * ny
                        sti["speed"] = math.hypot(sti["vx"], sti["vy"])
                        stj["speed"] = math.hypot(stj["vx"], stj["vy"])
                        pair_active[pair] = True
                else:
                    # became separated – allow a future collision
                    pair_active[pair] = False

        cur_frame += 1

    # 7. Return events sorted by time
    events.sort(key=lambda e: e["time"])
    return events
